#!/usr/bin/env bash
# FINNET deploy — gecikmiş alacağı NET pozisyona taşı (server + mobil + desktop). Regen + doğrula. Idempotent.
set -e
cd /opt/krb-assessment
set -a; [ -f .env ] && . ./.env; set +a
PW="${POSTGRES_PASSWORD:-}"
if [ -f shells/saha.js ]; then SAHA=shells/saha.js; else SAHA=$(find . -maxdepth 3 -name saha.js -not -path '*/backups/*' -not -path '*/node_modules/*'|head -1); fi
KOK=shells/kokpit.html
[ -f "$SAHA" ] || { echo "HATA: saha.js yok"; exit 1; }
[ -f "$KOK" ] || { echo "HATA: kokpit.html yok"; exit 1; }
cp server_container.mjs server_container.mjs.bak.$(date +%s)
cp "$SAHA" "$SAHA.bak.$(date +%s)"
cp "$KOK" "$KOK.bak.$(date +%s)"

echo "== server NET fix =="
printf '%s' '' | base64 -d > fix_finnet.py
python3 fix_finnet.py

echo "== mobil NET fix =="
SDIR=$(dirname "$SAHA")
printf '%s' '' | base64 -d > "$SDIR/fix_finnet_mobil.py"
( cd "$SDIR" && python3 fix_finnet_mobil.py ) && rm -f "$SDIR/fix_finnet_mobil.py"

echo "== desktop NET fix =="
printf '%s' '' | base64 -d > shells/fix_finnet_desktop.py
( cd shells && python3 fix_finnet_desktop.py ) && rm -f shells/fix_finnet_desktop.py

echo "== syntax =="
node --check server_container.mjs && echo SERVER_OK
node --check "$SAHA" && echo SAHA_OK

echo "== bugünkü satırı sil (net ile yeniden üret) =="
docker exec -i -e PGPASSWORD="$PW" krb-assessment-postgres \
  psql -U assessment_app -d assessment_platform -P pager=off -c "DELETE FROM bi_finansal_icgoru WHERE gun=CURRENT_DATE;"

docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
echo "== 95sn bekle =="
sleep 95
echo "== NET köprü (baglam.etki) =="
docker exec -i -e PGPASSWORD="$PW" krb-assessment-postgres \
  psql -U assessment_app -d assessment_platform -P pager=off -c \
  "SELECT baglam->'etki'->>'overdue_brut' brut, baglam->'etki'->>'overdue' net, baglam->'etki'->>'mahsup' mahsup, baglam->'etki'->>'finans_maliyeti_yil' finans_yil, baglam->'etki'->>'finans_pct_brutkar' pct_brutkar FROM bi_finansal_icgoru WHERE gun=CURRENT_DATE;"
echo "== en büyük NET gecikmiş hesaplar (kim) =="
docker exec -i -e PGPASSWORD="$PW" krb-assessment-postgres \
  psql -U assessment_app -d assessment_platform -P pager=off <<'SQL'
SELECT t->>'ad' musteri, t->>'rep' temsilci, t->>'overdue' net, t->>'brut' brut, t->>'krb_borc' krb_borc
FROM bi_finansal_icgoru, jsonb_array_elements(baglam->'koken'->'top') t
WHERE gun=CURRENT_DATE LIMIT 8;
SQL
echo "== içgörü başlıkları =="
docker exec -i -e PGPASSWORD="$PW" krb-assessment-postgres \
  psql -U assessment_app -d assessment_platform -P pager=off <<'SQL'
SELECT (e->>'siddet') siddet, left(e->>'baslik',50) baslik, e->>'etki_tl' etki_tl
FROM bi_finansal_icgoru, jsonb_array_elements(icgoruler) e WHERE gun=CURRENT_DATE;
SQL
echo "== DONE =="
